const res = await fetch('https://verification.didit.me/v3/kyb/shareholders/', {
  method: 'POST',
  headers: {
    'x-api-key': 'YOUR_API_KEY',
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    kyb_response_id: '69aeeb95febb0f1704042259',
    vendor_data: 'company-1234',
  }),
});
if (!res.ok) throw new Error(`Request failed: ${res.status}`);
const data = await res.json();
const requestId = data.request_id;
console.log('Keep this request ID:', requestId);
let company = data.kyb_registry;
if (res.status === 202 || company.fetch_status === 'pending') {
  // This client wait limit does not cancel the report or create a new purchase.
  const deadline = Date.now() + 300000;
  while (company.fetch_status !== 'resolved' && Date.now() < deadline) {
    await new Promise(resolve => setTimeout(resolve, 5000));
    const decisionResponse = await fetch(
      `https://verification.didit.me/v3/session/${requestId}/decision/`,
      { headers: { 'x-api-key': 'YOUR_API_KEY' }, signal: AbortSignal.timeout(30000) },
    );
    if (!decisionResponse.ok) throw new Error(`Retrieval failed: ${decisionResponse.status}`);
    const decision = await decisionResponse.json();
    company = decision.registry_checks?.[0]?.company ?? company;
  }
}
if (company.fetch_status === 'resolved') {
  console.log(company.company_name, company.registry_tier_delivered);
} else {
  console.log('Still processing; retrieve this request later:', requestId);
}

